    con.setAutoCommit(false);
    try (PreparedStatement ps = con.prepareStatement(
             "UPDATE stock SET available = available - ? WHERE id = ? AND available >= ?")) {
        ps.setInt(1, qty); ps.setInt(2, productId); ps.setInt(3, qty);
        if (ps.executeUpdate() != 1) throw new NotAvailableException(productId);
    }
    con.commit();
} catch (SQLException | RuntimeException e) { con.rollback(); throw e; }
finally { con.setAutoCommit(true); con.close(); }

